  Section Main.
    Variables (fx : FPState) (A0 : AS MI) (s : LibIface.SX ST) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model).
    Variables (sp ret obj1 bl1 bc1 obj2 bl2 bc2 : Z) (ents1 ents2 : list (Z * (Z * V))) (K : TSet).
    Hypothesis CB : callB MI ST A0 s R0 M0 model0 sp ret (MVA_STACK DEL_STACK).
    Hypothesis H10 : getr R0 10%bv = Z_to_bv 64 obj1.
    Hypothesis H11 : getr R0 11%bv = Z_to_bv 64 obj2.
    Hypothesis U1 : umapx MI NS nval A0 M0 obj1 bl1 bc1 ents1.
    Hypothesis U2 : umapx MI NS nval A0 M0 obj2 bl2 bc2 ents2.
    Hypothesis AS1 : above_sp MI A0 sp obj1 40.
    Hypothesis AS2 : above_sp MI A0 sp obj2 40.
    Hypothesis AP12 : apart obj1 40 obj2 40.
    Hypothesis DJ : forall b, In b (map fst (umap_blocks NS bl1 bc1 ents1)) -> ~ In b (map fst (umap_blocks NS bl2 bc2 ents2)).

    Definition FOOT (a : Z) : Prop := umap_foot NS obj1 bl1 bc1 ents1 a \/ umap_foot NS obj2 bl2 bc2 ents2 a.
    Definition W : Z * Z := (sp - MVA_STACK DEL_STACK, sp).

    #[local] Notation FOOT1 := (umap_foot NS obj1 bl1 bc1 ents1).
    #[local] Notation FOOTB := (fun a => umap_foot NS obj1 bl1 bc1 ents1 a \/ (obj2 <= a < obj2 + 40)).

    Definition frame (M : mem) : Prop :=
      cell8 SEGS M (sp - 8) ret /\ cell8 SEGS M (sp - 16) (bv_unsigned (getr R0 8%bv))
      /\ cell8 SEGS M (sp - 24) (bv_unsigned (getr R0 9%bv)) /\ cell8 SEGS M (sp - 32) (bv_unsigned (getr R0 18%bv)).

    Definition base_ok (R : bvmap 5 word) : Prop :=
      getr R 2%bv = Z_to_bv 64 (sp - 32) /\ getr R 3%bv = Z_to_bv 64 (ly_gp L) /\ getr R 4%bv = Z_to_bv 64 (ly_tp L)
      /\ getr R 8%bv = Z_to_bv 64 obj2 /\ getr R 9%bv = Z_to_bv 64 obj1
      /\ forall r, In r [19; 20; 21; 22; 23; 24; 25; 26; 27]%bv -> getr R r = getr R0 r.

    Lemma base_pres : forall R R', base_ok R -> pres PRES R R' -> base_ok R'.
Proof using L R0 sp obj1 obj2.
