    Record mid (A : AS MI) (M : mem) (model : Model) (R : bvmap 5 word) (ops : list lop) (F : Z -> Prop) : Prop := MID {
      md_ainv : ainv MI A M model;
      md_mstd : mstd model;
      md_fs : m_fs model = m_fs model0;
      md_fds : m_fds model = m_fds model0;
      md_base : base_ok R;
      md_frame : frame M;
      md_def : defined M (sp - 32 - DEL_STACK) (32 + DEL_STACK);
      md_eff : eff MI A0 A M0 M W F;
      md_lap : lapply (live MI A0) ops (live MI A);
      md_win : forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A a;
      md_own1 : forall i, 0 <= i < 40 -> ~ owned MI A (obj1 + i);
      md_own2 : forall i, 0 <= i < 40 -> ~ owned MI A (obj2 + i);
      md_hdef1 : defined M obj1 40;
      md_hdef2 : defined M obj2 40;

      md_nodes2 : forall p k v, In (p, (k, v)) ents2 -> agree_on M0 M p NS;
      md_bkt2 : bc2 <> 0 -> agree_on M0 M bl2 (8 * bc2);
      md_live2 : forall p n, In (p, n) (umap_blocks NS bl2 bc2 ents2) -> In (p, n) (live MI A)
    }.

